# ---------------------------------------------------------------------------
# Execution: Write Chunks & Update index.json (Strictly < 30 KB)
# ---------------------------------------------------------------------------

def process_rituals():
    print("\n🔔 Expanding Rituals (rituals/)...")
    idx_path = os.path.join(RITUALS_DIR, 'index.json')
    existing_items = []
    if os.path.exists(idx_path):
        with open(idx_path, 'r', encoding='utf-8') as f:
            existing_items = json.load(f).get('items', [])
    
    existing_ids = {it['id'] for it in existing_items}
    
    # Process new rituals
    for r in NEW_RITUALS:
        chunk_file = f"ritual-{r['slug']}.json"
        chunk_path = os.path.join(RITUALS_DIR, chunk_file)
        with open(chunk_path, 'w', encoding='utf-8') as f:
            json.dump(r, f, ensure_ascii=False, indent=2)
        
        if r['id'] not in existing_ids:
            preview = {
                'id': r['id'],
                'slug': r['slug'],
                'title': r['title'],
                'titleDevanagari': r['titleDevanagari'],
                'category': r['category'],
                'categoryHindi': r['categoryHindi'],
                'deity': r['deity'],
                'deityDevanagari': r['deityDevanagari'],
                'totalVerses': r['totalVerses'],
                'durationMinutes': r['durationMinutes'],
                'tags': r['tags'],
                'chunkFile': chunk_file
            }
            existing_items.append(preview)
            existing_ids.add(r['id'])
    
    manifest = {
        'category': 'rituals',
        'categoryHindi': 'नित्य उपासना, आरती एवं चालीसा',
        'count': len(existing_items),
        'updatedAt': '2026-11-18T08:00:00Z',
        'items': existing_items
    }
    with open(idx_path, 'w', encoding='utf-8') as f:
        json.dump(manifest, f, ensure_ascii=False, indent=2)
    
    sz = os.path.getsize(idx_path)
    print(f"  ✓ Total Rituals: {len(existing_items)}, index.json: {sz} bytes (limit: 30720)")
    assert sz < 30720, f"rituals/index.json exceeded 30 KB: {sz}"

def process_places():
    print("\n🏛️ Expanding Places (places/)...")
    idx_path = os.path.join(PLACES_DIR, 'index.json')
    all_places = {}
    
    # Load all existing place chunks
    for fn in os.listdir(PLACES_DIR):
        if fn.startswith('place-') and fn.endswith('.json'):
            fp = os.path.join(PLACES_DIR, fn)
            try:
                with open(fp, 'r', encoding='utf-8') as f:
                    d = json.load(f)
                    all_places[d['id']] = d
            except:
                pass
                
    # Add new places
    for p in NEW_PLACES:
        chunk_file = f"place-{p['slug']}.json"
        chunk_path = os.path.join(PLACES_DIR, chunk_file)
        with open(chunk_path, 'w', encoding='utf-8') as f:
            json.dump(p, f, ensure_ascii=False, indent=2)
        all_places[p['id']] = p
        
    # Build clean compact previews
    existing_items = []
    for pid, p in all_places.items():
        sig = p.get('briefSignificance', '')
        if len(sig) > 75:
            sig = sig[:72] + '...'
        preview = {
            'id': p['id'],
            'slug': p['slug'],
            'name': p.get('name', p['id']),
            'nameDevanagari': p.get('nameDevanagari', p.get('name', '')),
            'dhamRegion': p.get('dhamRegion', 'vrindavan'),
            'regionNameHindi': p.get('regionNameHindi', ''),
            'briefSignificance': sig,
            'deity': p.get('deityDevanagari', p.get('deity', '')),
            'tags': p.get('tags', [])[:3],
            'chunkFile': f"place-{p['slug']}.json"
        }
        existing_items.append(preview)
            
    manifest = {
        'category': 'places',
        'categoryHindi': 'श्री धाम, पवित्र तीर्थ एवं लीला स्थल',
        'count': len(existing_items),
        'updatedAt': '2026-11-18T08:00:00Z',
        'items': existing_items
    }
    with open(idx_path, 'w', encoding='utf-8') as f:
        json.dump(manifest, f, ensure_ascii=False, indent=2)
        
    sz = os.path.getsize(idx_path)
    print(f"  ✓ Total Places: {len(existing_items)}, index.json: {sz} bytes (limit: 30720)")
    assert sz < 30720, f"places/index.json exceeded 30 KB: {sz}"

