def verify_all_watermarks():
    print("\n🛡️ Verifying Zero Watermarks & Quality Gates across ALL sacred files...")
    forbidden = [
        'shrijirasik', 'vedickathas', 'bharatdevotion', 'bhaktiarohan',
        'santeknath.org', 'tukaram.com', 'scraped', 'harvested',
        'bhakti arohan', 'bharat devotion', 'vedic kathas'
    ]
    violations = []
    scanned = 0
    for c_dir in [RITUALS_DIR, PLACES_DIR, STORIES_DIR, BIOS_DIR]:
        for fn in os.listdir(c_dir):
            if not fn.endswith('.json'):
                continue
            scanned += 1
            fp = os.path.join(c_dir, fn)
            with open(fp, 'r', encoding='utf-8') as f:
                content = f.read().lower()
            for term in forbidden:
                if term in content:
                    violations.append(f"{fn}: found '{term}'")
    
    if violations:
        print("❌ Violations found:")
        for v in violations:
            print(" ", v)
        sys.exit(1)
    print(f"🎉 SUCCESS: All {scanned} sacred JSON files 100% clean and compliant!")

if __name__ == '__main__':
    process_rituals()
    process_places()
    process_stories()
    process_bios()
    verify_all_watermarks()
    print("\n✨ Sacred Sections Corpus Extension Completed Successfully!")